import { mkdir, writeFile, readFile, unlink, rmdir } from "node:fs/promises";
import { join, dirname, resolve } from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";
import { CLAUDE_MARKETPLACE_MARKER, CLAUDE_MOD_MARKER, claudeModTargets, generateClaudeModFiles, } from "./claudeMod.js";
import { CODEX_HOOK_MARKER, generateCodexHookFiles } from "./codexHook.js";
import { CURSOR_HOOK_MARKER, generateCursorHookFiles } from "./cursorHook.js";
import { loadEngineBundle } from "./claudeBundle.js";
/**
 * Generates an OpenCode V2 plugin file and installs it into the project.
 *
 * Verified against OpenCode 2.2.0 (see VERIFY.md):
 *  - plugins auto-load from .opencode/plugins/ (ancestors too)
 *  - the shell tool's execute.after result looks like
 *    { output: { exit, truncated, output: "<text>" } }
 *  - the tool name is "shell" in V2 ("bash" in V1, no longer targeted)
 *
 * The plugin degrades to a no-op when the @opencode/plugin SDK or the
 * tokenshave engine is missing; failures are noted to
 * ~/.tokenshave/plugin-debug.log, never thrown.
 */
/** identity marker; uninstall only removes files carrying it */
export const INSTALL_MARKER = "tokenshave — generated by `npx tokenshave install`";
/** Project-local plugin location (OpenCode V2). */
export function pluginTargets(dir) {
    return [join(dir, ".opencode", "plugins", "tokenshave.ts")];
}
/** URL of this package's ESM entrypoint, usable in a dynamic `import()`. */
export function defaultPackageUrl() {
    // dist/src/install.js → package root is two levels up
    const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
    return pathToFileURL(join(root, "dist", "src", "index.js")).href;
}
export function generatePluginSource(pkgUrl, generatedAt) {
    return `// ${INSTALL_MARKER} on ${generatedAt}
// Uninstall with \`npx tokenshave uninstall\`, or just delete this file.
// Shaves shell tool output (npm/test/git noise) only. Marker lines in the
// returned text state exactly what was removed. A missing SDK or engine
// degrades to a no-op and is logged to ~/.tokenshave/plugin-debug.log.

import { appendFileSync, mkdirSync } from "node:fs"
import { homedir } from "node:os"
import { join } from "node:path"

const PKG_URL = ${JSON.stringify(pkgUrl)}

function note(msg) {
  try {
    const dir = join(homedir(), ".tokenshave")
    mkdirSync(dir, { recursive: true })
    appendFileSync(join(dir, "plugin-debug.log"), new Date().toISOString() + " " + msg + "\\n")
  } catch {}
}

const state = { mod: undefined }
async function getMod() {
  if (state.mod === undefined) {
    try {
      state.mod = await import(PKG_URL)
    } catch (e) {
      state.mod = null
      note("engine could not load, shaving disabled: " + String(e))
    }
  }
  return state.mod
}

function logStat(payload) {
  void getMod()
    .then((mod) => mod && mod.record(payload))
    .catch((e) => {
      try {
        note("record failed: " + String(e))
      } catch {}
    })
}

async function shaveToolText(tool, text) {
  const mod = await getMod()
  if (!mod) return text
  try {
    const r = mod.shave(tool, text)
    logStat({
      tool,
      rule: r.rule,
      rawLines: r.rawLines,
      keptLines: r.keptLines,
      rawTokens: r.rawTokens,
      keptTokens: r.keptTokens,
    })
    note("shave tool=" + tool + " rule=" + r.rule + " " + r.rawTokens + " -> " + r.keptTokens)
    return r.output
  } catch (e) {
    note("shave failed: " + String(e))
    return text
  }
}

// OpenCode V2 tool name is "shell" (V1 was "bash"); accept both spellings.
const SHELL_TOOL = /^(shell|bash)$/

// execute.after results for the shell tool look like:
//   { output: { exit, truncated, output: "<text>" } }
// plain-string outputs (custom plugins' tools) are supported too.
function pickText(result) {
  const o = result === null || result === undefined ? undefined : result.output
  if (typeof o === "string") return o
  if (o && typeof o === "object" && typeof o.output === "string") return o.output
  return null
}

const v2Sdk = await import("@opencode/plugin").catch((e) => {
  const err = e instanceof Error ? e.message : String(e)
  note("@opencode/plugin unavailable (this is a V1 install?), no-op: " + err)
  return undefined
})

// Shaving rules are keyed by the command, not the tool name — otherwise every
// OpenCode session runs under the generic rule only. event.input for the shell
// tool carries the command string.
function commandOf(event) {
  const input = event === null || event === undefined ? undefined : event.input
  if (input && typeof input.command === "string" && input.command.length > 0) return input.command
  return event === null || event === undefined ? "shell" : String(event.tool ?? "shell")
}

let plugin = undefined
if (v2Sdk) {
  plugin = v2Sdk.Plugin.define({
    id: "tokenshave",
    async setup(ctx) {
      try {
        await ctx.tool.hook("execute.after", async (event) => {
          try {
            if (event.status !== "completed") return
            if (!SHELL_TOOL.test(event.tool)) return
            const text = pickText(event.result)
            if (text === null || text.length < 50) return
            note("input shape: " + JSON.stringify(event.input).slice(0, 120))
            const cmd = commandOf(event)
            const shaved = await shaveToolText(cmd, text)
            if (shaved === text) return
            const o = event.result.output
            event.result = {
              ...event.result,
              output:
                o && typeof o === "object" ? { ...o, output: shaved } : shaved,
              metadata: { ...(event.result.metadata ?? {}), tokenshave: true },
            }
          } catch {}
        })
      } catch (e) {
        note("hook registration failed: " + String(e))
      }
    },
  })
}

export default plugin
`;
}
/** version of this tokenshave package, read from the shipped package.json */
async function packageVersion() {
    try {
        const root = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
        const raw = await readFile(join(root, "package.json"), "utf8");
        const pkg = JSON.parse(raw);
        return pkg.version ?? "0.0.0";
    }
    catch {
        return "0.0.0";
    }
}
const INSTALL_MARKERS = [INSTALL_MARKER, CLAUDE_MOD_MARKER, CLAUDE_MARKETPLACE_MARKER, CODEX_HOOK_MARKER, CURSOR_HOOK_MARKER];
/** project-local Cursor hook files (.cursor/hooks.json + self-contained wrapper script) */
export function cursorTargets(dir) {
    return {
        hooksJson: join(dir, ".cursor", "hooks.json"),
        wrapJs: join(dir, ".tokenshave", "tokenshave-cursor.js"),
    };
}
/** project-local Codex hook files (.codex/hooks.json + self-contained script) */
export function codexTargets(dir) {
    return {
        hooksJson: join(dir, ".codex", "hooks.json"),
        shaveJs: join(dir, ".tokenshave", "tokenshave-shave.js"),
    };
}
/** install all adapters: OpenCode V2 plugin, Claude Code mod, Codex CLI hook */
export async function installPlugins(dir, pkgUrl) {
    const url = pkgUrl ?? defaultPackageUrl();
    const generatedAt = new Date().toISOString();
    const source = generatePluginSource(url, generatedAt);
    const reports = [];
    // OpenCode V2 plugin
    for (const target of pluginTargets(dir)) {
        await mkdir(dirname(target), { recursive: true });
        const action = await writeIfOurs(target, INSTALL_MARKER, source);
        reports.push({ file: target, agent: "opencode", action });
    }
    // Claude Code mod (self-contained: engine inlined, zero imports)
    const engineBundle = await loadEngineBundle();
    const version = await packageVersion();
    const generated = generateClaudeModFiles(generatedAt, engineBundle, version);
    const targets = claudeModTargets(dir);
    for (const { target: key, content } of generated) {
        const target = targets[key];
        await mkdir(dirname(target), { recursive: true });
        const marker = key === "marketplaceJson" ? CLAUDE_MARKETPLACE_MARKER : CLAUDE_MOD_MARKER;
        const action = await writeIfOurs(target, marker, content);
        reports.push({ file: target, agent: "claude", action });
    }
    // Codex CLI project-local hook (.codex/hooks.json + inline-engine script)
    const codex = codexTargets(dir);
    const files = await generateCodexHookFiles(generatedAt, version, `node "${codex.shaveJs.replace(/\\/g, "/")}"`, engineBundle);
    const codexReports = [
        ["hooksJson", files.hooksJson],
        ["shaveJs", files.shaveJs],
    ];
    for (const [key, content] of codexReports) {
        const target = codex[key];
        await mkdir(dirname(target), { recursive: true });
        const action = await writeIfOurs(target, CODEX_HOOK_MARKER, content);
        reports.push({ file: target, agent: "codex", action });
    }
    // Cursor project-local hook (.cursor/hooks.json + dual-role wrapper script)
    const cursor = cursorTargets(dir);
    const cursorFiles = await generateCursorHookFiles(generatedAt, version, `node "${cursor.wrapJs.replace(/\\/g, "/")}"`, engineBundle);
    const cursorReports = [
        ["hooksJson", cursorFiles.hooksJson],
        ["wrapJs", cursorFiles.wrapJs],
    ];
    for (const [key, content] of cursorReports) {
        const target = cursor[key];
        await mkdir(dirname(target), { recursive: true });
        // the generated hooks.json carries no marker FIELD (Cursor's schema is
        // strict and extra keys are not a documentable risk): identity is the
        // hook command pointing at the generated wrapper script's filename
        const oursIf = key === "hooksJson" ? (existing) => existing.includes("tokenshave-cursor.js") : undefined;
        const action = await writeIfOurs(target, CURSOR_HOOK_MARKER, content, oursIf);
        reports.push({ file: target, agent: "cursor", action });
    }
    return reports;
}
async function writeIfOurs(target, marker, content, oursIf) {
    let existing = null;
    try {
        existing = await readFile(target, "utf8");
    }
    catch {
        existing = null;
    }
    if (existing !== null) {
        const ours = INSTALL_MARKERS.some((m) => existing.includes(m)) || (oursIf?.(existing) ?? false);
        return ours ? "skipped-existing" : "left-foreign-file";
    }
    await writeFile(target, content, "utf8");
    return "created";
}
/** every file install Plugins ever wrote for Claude Code, in cleanup order */
function claudeCleanupTargets(dir) {
    const t = claudeModTargets(dir);
    return [t.registerJs, t.hooksJson, t.pluginJson, t.readme, t.marketplaceJson];
}
export async function uninstallPlugins(dir) {
    const reports = [];
    for (const target of pluginTargets(dir)) {
        try {
            const content = await readFile(target, "utf8");
            if (INSTALL_MARKERS.some((m) => content.includes(m))) {
                await unlink(target);
                reports.push({ file: target, agent: "opencode", action: "removed" });
            }
            else {
                reports.push({ file: target, agent: "opencode", action: "left-foreign-file" });
            }
        }
        catch {
            reports.push({ file: target, agent: "opencode", action: "not-built" });
        }
    }
    for (const target of claudeCleanupTargets(dir)) {
        try {
            const content = await readFile(target, "utf8");
            if (INSTALL_MARKERS.some((m) => content.includes(m))) {
                await unlink(target);
                reports.push({ file: target, agent: "claude", action: "removed" });
            }
            else {
                reports.push({ file: target, agent: "claude", action: "left-foreign-file" });
            }
        }
        catch {
            reports.push({ file: target, agent: "claude", action: "not-built" });
        }
    }
    const codex = codexTargets(dir);
    for (const target of [codex.hooksJson, codex.shaveJs]) {
        try {
            const content = await readFile(target, "utf8");
            if (INSTALL_MARKERS.some((m) => content.includes(m))) {
                await unlink(target);
                reports.push({ file: target, agent: "codex", action: "removed" });
            }
            else {
                reports.push({ file: target, agent: "codex", action: "left-foreign-file" });
            }
        }
        catch {
            reports.push({ file: target, agent: "codex", action: "not-built" });
        }
    }
    const cursor = cursorTargets(dir);
    for (const [target, identity] of [
        [cursor.hooksJson, (c) => c.includes("tokenshave-cursor.js")],
        [cursor.wrapJs, (c) => INSTALL_MARKERS.some((m) => c.includes(m))],
    ]) {
        try {
            const content = await readFile(target, "utf8");
            if (identity(content)) {
                await unlink(target);
                reports.push({ file: target, agent: "cursor", action: "removed" });
            }
            else {
                reports.push({ file: target, agent: "cursor", action: "left-foreign-file" });
            }
        }
        catch {
            reports.push({ file: target, agent: "cursor", action: "not-built" });
        }
    }
    removeEmptyClaudeDirs(dir).catch(() => { });
    return reports;
}
/** remove the generated directory skeleton if nothing is left in it */
async function removeEmptyClaudeDirs(dir) {
    const t = claudeModTargets(dir);
    for (const candidate of [
        dirname(t.registerJs), // .../mod/hooks
        dirname(t.pluginJson), // .../mod/.claude-plugin
        dirname(t.readme), // .../mod
        dirname(t.marketplaceJson), // .../.tokenshave/claude
        dirname(dirname(t.marketplaceJson)), // .../.tokenshave
    ]) {
        try {
            await rmdir(candidate); // only succeeds when empty — never deletes content
        }
        catch {
            break;
        }
    }
}
